sourceUnits.src/counter/main.atto:
namespace counter;
pub async routine main(): void {
  val worker = spawn Counter();
  await worker.get_ready();
  worker.send(1);
  worker.send(2);
  worker.send(3);
  worker.send(4);
  val a = (await worker.outputs.next()).value.unwrap();
  val b = (await worker.outputs.next()).value.unwrap();
  val c = (await worker.outputs.next()).value.unwrap();
  val d = (await worker.outputs.next()).value.unwrap();
  stdio.stdout.write(a.value);
  stdio.stdout.write("|");
  stdio.stdout.write(b.value);
  stdio.stdout.write("|");
  stdio.stdout.write(c.value);
  stdio.stdout.write("|");
  stdio.stdout.write(d.value);
  await worker.get_done();
  return;
}

sourceUnits.src/counter/receive.atto:
namespace counter;
// State views never escape the intrinsic. A detached Copy scalar is read
// under the loan; mailbox publication follows only after scope exit.
external mtd (Counter c) receive(ActorMail<int> mail): void {
  self.handle_state(critical-write |s| -> {
    s.total = s.total + mail.value;
  });
  // Detached immutable scalar; no actor-state loan crosses mailbox admission.
  val int snapshot = self.handle_state(critical-read |s| -> s.total);
  self.send(snapshot);
  if mail.value == 4; do
    self.end();
  fi
  return;
}

